{"files": [{"path": "characters.json", "content": "{
  "main_characters": [
    {
      "name": "张麻子 / 约翰·马斯顿 (John Marston)",
      "role": "protagonist",
      "identity": "表面身份为赴任鹅城的县长张麻子，真实身份为来自西部的亡命之徒约翰·马斯顿",
      "traits": ["冷幽默", "暴烈果决", "重情重义", "反权威", "浪漫主义的实用主义者"],
      "overt_motivation": "以县长身份进入鹅城，瓦解黄四郎的统治",
      "covert_motivation": "寻找失踪的亚瑟·摩根和范德林德帮的残存成员，完成对旧日兄弟的承诺",
      "secret_fear": "害怕自己终究和达奇一样——为了目标不惜牺牲身边的人。凉粉桌上六子的命运就是他恐惧的镜像。",
      "misperception_of_other": "认为黄四郎只是一个普通的地方恶霸，低估了碉楼背后隐藏的跨时空秘密",
      "hidden_connection": "他脸上的伤疤不是麻子，是西部决斗留下的弹痕——这也是他与亚瑟·摩根最后一次并肩作战的印记"
    },
    {
      "name": "黄四郎",
      "role": "deuteragonist",
      "identity": "鹅城首富、实际统治者，碉楼深处隐藏着不属于这个时代的秘密",
      "traits": ["阴鸷狡诈", "表面儒雅", "极度控制欲", "对恐惧的艺术家"],
      "overt_motivation": "维持对鹅城的绝对统治，消灭一切挑战者",
      "covert_motivation": "碉楼地下关着的东西是他权力的真正来源——他需要的不是钱，是来自另一个世界的'货物'",
      "secret_fear": "害怕有人发现碉楼地下室的秘密，害怕'那边'的人找过来清算",
      "misperception_of_other": "认为张麻子只是又一个想捞钱的县长，没意识到对方是来自'那边'的猎人",
      "hidden_connection": "他与范德林德帮的关系——他可能是帮派背叛者的东方代理人，或者更黑暗的存在"
    }
  ],
  "supporting_characters": [
    {
      "name": "六子",
      "function": "反转点",
      "identity": "张麻子麾下最年轻的兄弟，凉粉事件的当事人",
      "description": "原本是故事中的牺牲品角色，但在这个版本中暴起反杀胡万，成为改变整个叙事走向的关键人物。他代表了'拒绝被剧本杀死的人'。热血、鲁莽但有惊人的直觉和枪法。"
    },
    {
      "name": "汤师爷 / '假马师'",
      "function": "助力",
